package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct { // 01 LOAN-REC, 21 bytes
	LrAcct      string          // PIC X(6) @0 len=6
	LrPrincipal decimal.Decimal // PIC 9(7)V99 @6 len=9
	LrRate      decimal.Decimal // PIC 9(2)V99 @15 len=4
	LrYears     int64           // PIC 9(2) @19 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsInterest decimal.Decimal // PIC 9(9)V99 len=11 = 0
var WsTotal decimal.Decimal // PIC 9(11)V99 len=13 = 0
var WsCount int64 // PIC 9(5) len=5 = 0
var WsPrinEd string // PIC Z,ZZZ,ZZ9.99 len=12
var WsIntEd string // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsTotalEd string // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var loanRec LoanRec

var inputLines []string
var inputIdx int
var inputDone bool

func pow10(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func pow10Decimal(exp int) decimal.Decimal {
	return decimal.New(1, int32(exp))
}

func parseDigitsToInt64(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	// keep only digits, handle sign? assume digits
	var v int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= '0' && c <= '9' {
			v = v*10 + int64(c-'0')
		} else if c == ' ' {
			continue
		} else {
			// unexpected char, treat as 0? ignore
		}
	}
	return v
}

func fitUnsigned(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	// keep low-order digits that fit: modulo 10^(intDigits+scale) on scaled integer
	totalDigits := intDigits + scale
	mod := pow10Decimal(totalDigits)
	// work with truncated/rounded value already at scale; get scaled int
	// Use Truncate to avoid extra fraction
	t := v.Truncate(int32(scale))
	neg := t.IsNegative()
	a := t.Abs()
	scaled := a.Shift(int32(scale))
	// scaled should be integer
	qi := scaled.IntPart() // fits within 64? may overflow for large; use Mod
	// Use decimal mod to be safe
	qd := decimal.NewFromInt(qi)
	// If scaled exceeds int64, IntPart may overflow; fallback using Mod directly
	// Use decimal Mod
	rem := scaled.Mod(mod)
	if neg {
		rem = rem.Neg()
	}
	return rem.Shift(int32(-scale))
}

func formatEdited(v decimal.Decimal, picture string) string {
	dot := strings.Index(picture, ".")
	var intPic, decPic string
	if dot >= 0 {
		intPic = picture[:dot]
		decPic = picture[dot+1:]
	} else {
		intPic = picture
		decPic = ""
	}
	intPlaceCount := 0
	for i := 0; i < len(intPic); i++ {
		if intPic[i] == 'Z' || intPic[i] == '9' {
			intPlaceCount++
		}
	}
	decPlaceCount := 0
	for i := 0; i < len(decPic); i++ {
		if decPic[i] == 'Z' || decPic[i] == '9' {
			decPlaceCount++
		}
	}
	neg := v.IsNegative()
	av := v.Abs().Truncate(int32(decPlaceCount))
	scaled := av.Shift(int32(decPlaceCount))
	// scaled integer value
	// Use string conversion via IntPart with mod handling for large? Values fit in int64 here.
	// To be safe use decimal mod/div
	modInt := pow10Decimal(intPlaceCount + decPlaceCount)
	scaledMod := scaled.Mod(modInt)
	intValDec := scaledMod.QuotientRemainder(pow10Decimal(decPlaceCount))
	_ = intValDec
	// simpler with int64 since sizes small (max 13 digits)
	intPartInt := scaledMod.Div(pow10Decimal(decPlaceCount)).IntPart()
	fracPartInt := scaledMod.Mod(pow10Decimal(decPlaceCount)).IntPart()
	if intPartInt < 0 {
		intPartInt = -intPartInt
	}
	if fracPartInt < 0 {
		fracPartInt = -fracPartInt
	}
	// low-order truncation already via mod; build zero-padded int string
	intStr := fmt.Sprintf("%0*d", intPlaceCount, intPartInt)
	// if intPlaceCount large, Sprintf handles; if overflow digits longer, keep rightmost
	if len(intStr) > intPlaceCount {
		intStr = intStr[len(intStr)-intPlaceCount:]
	}
	firstNZ := -1
	for i := 0; i < len(intStr); i++ {
		if intStr[i] != '0' {
			firstNZ = i
			break
		}
	}
	var b strings.Builder
	digitIdx := 0
	for i := 0; i < len(intPic); i++ {
		ch := intPic[i]
		switch ch {
		case 'Z':
			d := intStr[digitIdx]
			digitIdx++
			if firstNZ == -1 || digitIdx-1 < firstNZ {
				b.WriteByte(' ')
			} else {
				b.WriteByte(d)
			}
		case '9':
			d := intStr[digitIdx]
			digitIdx++
			b.WriteByte(d)
		case ',':
			// suppressed if no nonzero to the left
			suppress := false
			if firstNZ == -1 {
				suppress = true
			} else if firstNZ >= digitIdx {
				suppress = true
			} else {
				suppress = false
			}
			if suppress {
				b.WriteByte(' ')
			} else {
				b.WriteByte(',')
			}
		default:
			b.WriteByte(ch)
		}
	}
	if dot >= 0 {
		b.WriteByte('.')
		fracStr := fmt.Sprintf("%0*d", decPlaceCount, fracPartInt)
		if len(fracStr) > decPlaceCount {
			fracStr = fracStr[len(fracStr)-decPlaceCount:]
		}
		// decPic assumed all 9s; just write digits
		// if picture has Z in decimals, handle similarly (not needed)
		di := 0
		for i := 0; i < len(decPic); i++ {
			ch := decPic[i]
			if ch == 'Z' || ch == '9' {
				b.WriteByte(fracStr[di])
				di++
			} else {
				b.WriteByte(ch)
			}
		}
		_ = neg
	}
	return b.String()
}

func formatCount9(n int64, width int) string {
	m := pow10(width)
	v := n % m
	if v < 0 {
		v += m
	}
	return fmt.Sprintf("%0*d", width, v)
}

func loadInput() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file doesn't exist, treat as empty? COBOL would error; exit non-zero
		// Check if not exist -> empty input (no records)
		if os.IsNotExist(err) {
			inputLines = []string{}
			inputIdx = 0
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	// allow long lines
	sc.Buffer(make([]byte, 1024*1024), 1024*1024)
	var lines []string
	for sc.Scan() {
		line := sc.Text()
		// Strip trailing \r if present (Scanner strips \n, keeps \r? Actually ScanLines strips \r)
		// bufio.ScanLines already strips trailing \r, so nothing extra
		lines = append(lines, line)
	}
	if err := sc.Err(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	inputLines = lines
	inputIdx = 0
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func ReadPara() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		inputDone = true
		return
	}
	raw := inputLines[inputIdx]
	inputIdx++
	// pad with spaces on right if shorter than 21
	if len(raw) < 21 {
		raw = raw + strings.Repeat(" ", 21-len(raw))
	}
	if len(raw) > 21 {
		raw = raw[:21]
	}
	acct := raw[0:6]
	prStr := raw[6:15]
	rateStr := raw[15:19]
	yrStr := raw[19:21]
	pn := parseDigitsToInt64(prStr)
	rn := parseDigitsToInt64(rateStr)
	yn := parseDigitsToInt64(yrStr)
	loanRec.LrAcct = padRight(acct, 6)
	loanRec.LrPrincipal = decimal.New(pn, -2)
	loanRec.LrRate = decimal.New(rn, -2)
	loanRec.LrYears = yn
}

func ProcessPara() {
	// COMPUTE WS-INTEREST ROUNDED = LR-PRINCIPAL * LR-RATE * LR-YEARS / 100
	raw := loanRec.LrPrincipal.Mul(loanRec.LrRate).Mul(decimal.NewFromInt(loanRec.LrYears)).Shift(-2)
	rounded := raw.Round(2)
	WsInterest = fitUnsigned(rounded, 9, 2)
	// ADD WS-INTEREST TO WS-TOTAL
	WsTotal = fitUnsigned(WsTotal.Add(WsInterest), 11, 2)
	// ADD 1 TO WS-COUNT
	WsCount = (WsCount + 1) % 100000
	// MOVEs
	WsPrinEd = formatEdited(loanRec.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")
	fmt.Println(loanRec.LrAcct+" "+WsPrinEd+" "+WsIntEd)
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	fmt.Println("RECORDS: " + formatCount9(WsCount, 5))
	fmt.Println("TOTAL INTEREST: " + WsTotalEd)
}

func MainPara() {
	loadInput()
	WsEofFlag = "N"
	WsInterest = decimal.New(0, 0)
	WsTotal = decimal.New(0, 0)
	WsCount = 0
	inputDone = false
	ReadPara()
	// sync flag
	if WsEofFlag == "Y" {
		inputDone = true
	}
	for !inputDone {
		ProcessPara()
		if WsEofFlag == "Y" {
			inputDone = true
		} else {
			inputDone = false
		}
		// INPUT-DONE 88 based on WsEofFlag; keep consistent
		if WsEofFlag == "Y" {
			inputDone = true
		}
	}
	SummaryPara()
}

func main() {
	MainPara()
}

